@startuml
class OilCompany {}
class GasStation {}
class Pump {
  +gasolineType : string
  +currentLevel : float
  +reorderingLevel : float
  +criticalLevel : float
  +isBlocked : boolean
}
class Reservoir {}
class Customer {
  +isSuspended : boolean
}
class RefuelCard {}
class RefuelTurn {
  +amount : float
  +date : date
}
class MonthlyInvoice {
  +month : string
  +discount : float
}
class Payment {}
class Car {}

OilCompany "1" *-- "*" GasStation
GasStation "1" *-- "*" Pump
Pump "1" *-- "1" Reservoir
Pump "0..1" -- "0..1" Car : refuels
Pump "1" -- "*" RefuelTurn

Customer "0..1" -- "0..1" RefuelCard : holds
Customer "1" -- "*" MonthlyInvoice : receives
Customer "1" -- "*" Payment : makes
MonthlyInvoice "1" -- "*" RefuelTurn : includes
MonthlyInvoice "1" -- "0..1" Payment : settled by

@enduml

